class Integration(SchemaObject):
    """
        GitHub apps are a new way to extend GitHub. They can be installed directly on organizations and user accounts and granted access to specific repositories. They come with granular permissions and built-in webhooks. GitHub apps are first class actors within GitHub.
    """
    id = Field(int, required=True, description="Unique identifier of the GitHub app")
    slug = Field(str, description="The slug name of the GitHub app")
    node_id = Field(str, required=True)
    client_id = Field(str)
    owner = Field(Union["SimpleUser", "Enterprise"], required=True)
    name = Field(str, required=True, description="The name of the GitHub app")
    description = Field(Optional[str], required=True)
    external_url = Field(str, required=True)
    html_url = Field(str, required=True)
    created_at = Field(str, required=True)
    updated_at = Field(str, required=True)
    permissions = Field(Dict[str, Any], required=True, description="The set of permissions for the GitHub app")
    events = Field(List[str], required=True, description="The list of events for the GitHub app. Note that the `installation_target`, `security_advisory`, and `meta` events are not included because they are global events and not specific to an installation.")
    installations_count = Field(int, description="The number of installations associated with the GitHub app. Only returned when the integration is requesting details about itself.")


