    rules = Field(List[Union["RepositoryRuleCreation", "RepositoryRuleUpdate", "RepositoryRuleDeletion", "RepositoryRuleRequiredLinearHistory", "RepositoryRuleMergeQueue", "RepositoryRuleRequiredDeployments", "RepositoryRuleRequiredSignatures", "RepositoryRulePullRequest", "RepositoryRuleRequiredStatusChecks", "RepositoryRuleNonFastForward", "RepositoryRuleCommitMessagePattern", "RepositoryRuleCommitAuthorEmailPattern", "RepositoryRuleCommitterEmailPattern", "RepositoryRuleBranchNamePattern", "RepositoryRuleTagNamePattern", "RepositoryRuleFilePathRestriction", "RepositoryRuleMaxFilePathLength", "RepositoryRuleFileExtensionRestriction", "RepositoryRuleMaxFileSize", "RepositoryRuleWorkflows", "RepositoryRuleCodeScanning"]])
    created_at = Field(str)
    updated_at = Field(str)


